import json
import os
import sys
from datetime import datetime
from pathlib import Path

def parse_date(date_str):
    """Parse date string in YYYYMMDD format to datetime.date object."""
    if not date_str or date_str.strip() == "":
        return None
    try:
        return datetime.strptime(date_str.strip(), "%Y%m%d").date()
    except ValueError:
        return None

def load_fda_data(packet_dir):
    """Load FDA enforcement reports from JSON file."""
    file_path = Path(packet_dir) / "fda_enforcement_reports.json"
    with open(file_path, 'r') as f:
        data = json.load(f)
    # Create mapping from recall_number to record
    records = {}
    for record in data.get("results", []):
        recall_num = record.get("recall_number")
        if recall_num:
            records[recall_num] = record
    return records

def extract_fact_value(record, fact_name):
    """Extract fact value from record based on fact name."""
    if fact_name == "initiation date":
        return record.get("recall_initiation_date")
    elif fact_name == "classification date":
        return record.get("center_classification_date")
    elif fact_name == "termination date":
        return record.get("termination_date")
    return None

def process_pair(pair, facts, fda_records):
    """Process a single rule_id::entity pair."""
    rule_id, entity = pair.split("::", 1)
    required_facts = facts[rule_id]

    result = {}
    record = fda_records.get(entity)

    if not record:
        # If no record found, all facts are ABSENT
        for fact in required_facts:
            result[fact] = "ABSENT"
        return result

    for fact in required_facts:
        value = extract_fact_value(record, fact)
        if not value or value == "":
            result[fact] = "ABSENT"
        else:
            # Format date if it's a date field
            if "date" in fact:
                parsed = parse_date(value)
                if parsed:
                    value = parsed.strftime("%Y-%m-%d")
            result[fact] = [value, "fda_enforcement_reports"]

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Load manifest
    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    # Load FDA data
    fda_records = load_fda_data(packet_dir)

    # Process all pairs
    output = {}
    for pair in manifest["pairs"]:
        output[pair] = process_pair(pair, manifest["facts"], fda_records)

    # Output as JSON
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
