import json
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path

def parse_date(date_str):
    """Parse date string in YYYYMMDD format to datetime.date object."""
    if not date_str or date_str.strip() == "":
        return None
    try:
        return datetime.strptime(date_str.strip(), "%Y%m%d").date()
    except ValueError:
        return None

def load_fda_data(packet_dir):
    """Load FDA enforcement reports from JSON file."""
    file_path = Path(packet_dir) / "fda_enforcement_reports.json"
    with open(file_path, 'r') as f:
        data = json.load(f)

    # Create mapping from recall_number to record
    records = {}
    for record in data.get("results", []):
        recall_num = record.get("recall_number")
        if recall_num:
            records[recall_num] = record
    return records

def process_pair(pair, facts, fda_records):
    """Process a single rule_id::entity pair and return fact values."""
    rule_id, entity = pair.split("::", 1)
    result = {}

    # Get the record for this entity (recall number)
    record = fda_records.get(entity)

    for fact_name in facts[rule_id]:
        if fact_name == "initiation date":
            if record and "recall_initiation_date" in record:
                date_str = record["recall_initiation_date"]
                if date_str and date_str.strip():
                    # Convert YYYYMMDD to YYYY-MM-DD
                    try:
                        date_obj = parse_date(date_str)
                        if date_obj:
                            result[fact_name] = [date_obj.strftime("%Y-%m-%d"), "fda_enforcement_reports"]
                        else:
                            result[fact_name] = "ABSENT"
                    except:
                        result[fact_name] = "ABSENT"
                else:
                    result[fact_name] = "ABSENT"
            else:
                result[fact_name] = "ABSENT"

        elif fact_name == "classification date":
            if record and "center_classification_date" in record:
                date_str = record["center_classification_date"]
                if date_str and date_str.strip():
                    try:
                        date_obj = parse_date(date_str)
                        if date_obj:
                            result[fact_name] = [date_obj.strftime("%Y-%m-%d"), "fda_enforcement_reports"]
                        else:
                            result[fact_name] = "ABSENT"
                    except:
                        result[fact_name] = "ABSENT"
                else:
                    result[fact_name] = "ABSENT"
            else:
                result[fact_name] = "ABSENT"

        elif fact_name == "termination date":
            if record and "termination_date" in record:
                date_str = record["termination_date"]
                if date_str and date_str.strip():
                    try:
                        date_obj = parse_date(date_str)
                        if date_obj:
                            result[fact_name] = [date_obj.strftime("%Y-%m-%d"), "fda_enforcement_reports"]
                        else:
                            result[fact_name] = "ABSENT"
                    except:
                        result[fact_name] = "ABSENT"
                else:
                    result[fact_name] = "ABSENT"
            else:
                result[fact_name] = "ABSENT"

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Load manifest
    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    # Load FDA data
    fda_records = load_fda_data(packet_dir)

